insert into public.place_descriptions(book_id,place_id,collection,name,area,kind,zoom,checked,status,note,method,position_source_id,narrative_source_id,metadata) values ('ulisse','pigeon-house','core','Pigeon House','Poolbeg, Dublin','historical',15,'2026-11-09','Approximate historic complex reference','Stephen turns towards the Pigeon House, without reaching it in the episode.','The archaeological coordinates locate the fort area as a reference to the historic Pigeon House complex; they do not locate Stephen on the strand.','ae1200da113c5eda53ca868ce1fc8bfe81aa2952ae4a4b025bd358f4492974ea','f5a318a6281ec879a9c391ba217a6766246c70e5139603c09916c9d3d2e64c0c','{"positionDescription":{"status":"reviewed","reviewedAt":"2026-11-09","texts":{"it":"Storico complesso del Pigeon House sulla penisola di Poolbeg. Il punto indica l’area del forte, nella direzione verso cui Stephen si volta sulla spiaggia.","en":"The historic Pigeon House complex on the Poolbeg peninsula. The point indicates the fort area, the direction in which Stephen turns on the strand.","fr":"Ensemble historique de Pigeon House sur la péninsule de Poolbeg. Le point indique le secteur du fort, vers lequel Stephen se tourne sur la grève.","es":"Conjunto histórico de Pigeon House en la península de Poolbeg. El punto señala la zona del fuerte, hacia la cual Stephen se vuelve en la playa."}},"additionalSources":[{"url":"https://www.riverrun.org.uk/JJD2.pdf","label":"James Joyce’s Dublin · map 6"}]}'::jsonb) on conflict do nothing;
insert into public.place_references(book_id,id,section_id,place_id,collection,ordinal,category,scene_text,source_id,metadata) values ('ulisse','3:core:pigeon-house',3,'pigeon-house','core',4,'mentioned','Stephen crosses the sand towards Pigeon House; the text does not narrate his arrival there.','f5a318a6281ec879a9c391ba217a6766246c70e5139603c09916c9d3d2e64c0c','{"explicitCategory":true}'::jsonb) on conflict do nothing;
insert into public.excerpts(book_id,id,section_id,reference_id,slot,language,type,quote,attribution,text_source_id,rights_source_id,metadata) values ('ulisse','3:core:pigeon-house:original',3,'3:core:pigeon-house','original','en','original','Broken hoops on the shore; at the land a maze of dark cunning nets; farther away chalkscrawled backdoors and on the higher beach a dryingline with two crucified shirts. Ringsend: wigwams of brown steersmen and master mariners. Human shells. He halted. I have passed the way to aunt Sara’s. Am I not going there? Seems not. No-one about. He turned northeast and crossed the firmer sand towards the Pigeonhouse.','James Joyce · Ulysses · 1922 · Chapter III','f5a318a6281ec879a9c391ba217a6766246c70e5139603c09916c9d3d2e64c0c','21f5ddc16c42981666952e8d2fe36af645a8542aa0034417c672e91792c00cf9','{"highlightTerms":["Pigeonhouse"],"reviewedAt":"2026-11-09"}'::jsonb) on conflict do nothing;
